{
  "name": "被控对象仿真组件",
  "name_en": "Plant Simulation Component",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用作控制实验中的被控对象/示例仪器。它以线程方式运行，可持续读取“探针”数值、更新内部状态，并配合离散 PI 控制示例进行测试、教学或算法验证，而不是直接控制特定实验硬件。",
  "description_en": "A non-physical software component representing a plant or example instrument for control experiments. It runs in its own thread, continuously reads probe values, updates internal state, and can be used with a discrete PI control example for testing, teaching, or algorithm validation rather than direct control of a specific lab instrument.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动组件线程。",
      "description_en": "Start the component thread."
    },
    {
      "action_name": "auto-quit",
      "description": "停止并退出组件线程。",
      "description_en": "Stop and quit the component thread."
    },
    {
      "action_name": "auto-run",
      "description": "运行线程主循环，持续读取探针值。",
      "description_en": "Run the main thread loop and continuously read probe values."
    },
    {
      "action_name": "auto-read_probes",
      "description": "读取指定探针的数值。",
      "description_en": "Read the value of the specified probe."
    },
    {
      "action_name": "auto-is_connected",
      "description": "获取组件是否处于活动并连接状态。",
      "description_en": "get whether the component is active and connected"
    },
    {
      "action_name": "auto-update",
      "description": "更新组件状态或参数。",
      "description_en": "Update the component state or parameters."
    },
    {
      "action_name": "auto-reset",
      "description": "重置组件状态。",
      "description_en": "Reset the component state."
    },
    {
      "action_name": "auto-controler_output",
      "description": "获取控制器输出值。",
      "description_en": "Get the controller output value."
    }
  ],
  "tag_hints": [
    "virtual plant",
    "control-loop simulation",
    "PI control",
    "threaded polling",
    "probe reading",
    "example instrument"
  ]
}

